import{_ as o,o as i,c as a,j as e,a as r,aa as n}from"./chunks/framework.BAs_AphD.js";const s="/buildary-help-preview/media/en/diary/en_dennizaznamyprace2.jpg",d="/buildary-help-preview/media/en/diary/en_dennizaznamyprac3.jpg",l="/buildary-help-preview/media/en/diary/en_dennizaznamyprace4.jpg",c="/buildary-help-preview/media/en/diary/en_dennizaznamyprace5.jpg",h="/buildary-help-preview/media/en/diary/en_dennizaznamyprace6.jpg",p="/buildary-help-preview/media/en/diary/en_zmenaporadizaznamu.jpg",_=JSON.parse('{"title":"Daily Entries - Works Performed","description":"","frontmatter":{"title":"Daily Entries - Works Performed","wiki":"en:diary:dailyentriesworks"},"headers":[],"relativePath":"en/diary/dailyentriesworks.md","filePath":"en/diary/dailyentriesworks.md","lastUpdated":1794388980000}'),m={name:"en/diary/dailyentriesworks.md"};function g(f,t,y,u,w,b){return i(),a("div",null,[...t[0]||(t[0]=[e("h1",{id:"daily-entries-works-performed",tabindex:"-1"},[r("Daily Entries - Works Performed "),e("a",{class:"header-anchor",href:"#daily-entries-works-performed","aria-label":'Permalink to "Daily Entries - Works Performed"'},"​")],-1),e("h3",{id:"video-for-the-works-performed-section",tabindex:"-1"},[r("Video for the Works Performed Section "),e("a",{class:"header-anchor",href:"#video-for-the-works-performed-section","aria-label":'Permalink to "Video for the Works Performed Section"'},"​")],-1),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/cqFztSwwmos",title:"YouTube video",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),n('<h2 id="works-performed" tabindex="-1">Works Performed <a class="header-anchor" href="#works-performed" aria-label="Permalink to &quot;Works Performed&quot;">​</a></h2><p>To add an entry, use the <strong>+ New Entry</strong> button, which opens the editing window. Enter a description of the work being performed in the <strong>Description</strong> field and fill in any other required fields according to the diary settings. The <strong>Save and New</strong> option saves the entry and clears the form for entering a new record; the <strong>Save</strong> option saves the entry and closes the window.</p><figure class="shot" style="--w:600px;"><img src="'+s+'" alt="" width="400" loading="lazy"></figure><p>You can add <strong>attachments</strong> to entries either by dragging file(s) into the attachment field or by clicking <strong>Upload Attachment</strong> and then selecting the file from the file browser. Any file format up to 30 MB can be used as an attachment, with up to 20 attachments per entry. The application itself does not restrict the formats of uploaded attachments, but the Domain Administrator can disable any attachment type for the domain.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Be careful with <strong>compressed files</strong> such as ZIP, RAR, ARJ, etc. Most <strong>free</strong> versions of PDF editors do not allow attachments in compressed formats to be downloaded from a PDF file. Therefore, we do not recommend adding compressed files as attachments. The Domain Administrator can disable the uploading of these file types in Domain Settings.</p></div><figure class="shot" style="--w:600px;"><img src="'+d+'" alt="" width="400" loading="lazy"></figure><p>If the <strong>Performed Works</strong> module is active on the construction site and a budget has been uploaded, Works Performed can be entered using budget items. In this case, the <strong>Item Description</strong> field must be displayed in Diary Settings, on the Works Performed tab. The text of the selected item in the entry can be edited. The database retains the link to the original item, and editing the text does not break this link.</p><figure class="shot" style="--w:600px;"><img src="'+l+'" alt="" width="400" loading="lazy"></figure><p>Especially for linear construction projects, the functionality for locating Works Performed on a map can be useful. To enable location data to be entered on the map for individual entries, the <strong>Location</strong> field must be displayed in Diary Settings, on the Works Performed tab.</p><figure class="shot" style="--w:600px;"><img src="'+c+'" alt="" width="450" loading="lazy"></figure><p>It is also possible to locate work on the construction site by placing markers directly on a plan. To use this functionality, the <strong>plan</strong> field must be displayed in Diary Settings, on the Performed Works tab, and at least one plan must be uploaded under Project Settings → <strong>Project Sections and Plans</strong>.</p><figure class="shot" style="--w:600px;"><img src="'+h+'" alt="" width="400" loading="lazy"></figure><p>The <strong>Plan</strong> icon on an entry indicates that the work has been linked to a drawing.</p><p>Similarly, the <strong>Location</strong> icon indicates that the entry has been linked to a location on the map.</p><h3 id="changing-the-order-of-entries" tabindex="-1">Changing the Order of Entries <a class="header-anchor" href="#changing-the-order-of-entries" aria-label="Permalink to &quot;Changing the Order of Entries&quot;">​</a></h3><p>The Diary Administrator has permission to change the order of entries in the Works Performed (and Other Entries) section by dragging an entry to the desired position. This option can be disabled in Diary Settings. <img src="'+p+'" alt="" width="600" loading="lazy"></p>',16)])])}const P=o(m,[["render",g]]);export{_ as __pageData,P as default};
